// One SSE connection per loaded browser page.
window.eventSource = new EventSource("/events/stream/");

window.eventSource.onopen = () => {
    console.log("[SSE] Connection opened");
};

window.eventSource.onerror = (error) => {
    console.error("[SSE] Connection error:", error);
};

// Heartbeats are generated by Django every 15 seconds
// when there are no other events.
window.eventSource.addEventListener(
    "heartbeat",
    (event) => {
        try {
            const data = JSON.parse(event.data);

            console.log(
                "[SSE] Heartbeat:",
                data
            );
        } catch (error) {
            console.error(
                "[SSE] Could not parse heartbeat:",
                error
            );
        }
    }
);

// Close the SSE connection when navigating away.
window.addEventListener(
    "pagehide",
    () => {
        if (window.eventSource) {
            window.eventSource.close();
        }
    }
);